def replace_placeholders_in_doc(doc: Document, values: list) -> int:
    """替换整个 docx 中的【】占位符（按文档顺序）。

    参数 values 是按【】出现顺序排列的替换值，函数内部按段落顺序消费。
    """
    value_idx = 0
    total_used = 0
    # 段落
    for p in doc.paragraphs:
        if value_idx >= len(values):
            break
        remaining = len(values) - value_idx
        used = replace_placeholders_by_position(p, values[value_idx:value_idx + remaining])
        value_idx += used
        total_used += used
    # 表格（如果有）
    if value_idx < len(values):
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    if value_idx >= len(values):
                        break
                    for p in cell.paragraphs:
                        if value_idx >= len(values):
                            break
                        remaining = len(values) - value_idx
                        used = replace_placeholders_by_position(p, values[value_idx:value_idx + remaining])
                        value_idx += used
                        total_used += used
    return total_used

replacements.original_text:
def replace_placeholders_in_doc(doc: Document, values: list) -> int:
    """替换整个 docx 中的【】占位符（按文档顺序）。"""
    total = 0
    # 段落
    for p in doc.paragraphs:
        total += replace_placeholders_by_position(p, values)
        if total >= len(values):
            break  # 所有值都用完了
    # 表格（如果有）
    if total < len(values):
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for p in cell.paragraphs:
                        used = replace_placeholders_by_position(p, values[total:])
                        total += used
                        if total >= len(values):
                            break
    return total

